      prop: () => F('136,112 160,104 184,112 176,120 160,116 144,120', '#c99a2e', 0.16) + F('146,110 148,86 160,82 172,86 174,110 160,106', '#f0c14b', 0.2) + P('147,102 160,98 173,102 174,110 160,106 146,110', '#3d2b63')
