    // 闭着眼喝茶，学生的事随缘
    '佛系放养': (crop) => bust({ c: '#7d9a94', hair: '#e7e7e2', hairStyle: 'bald', brow: 'soft', browColor: '#d2d2cc', eyes: 'closed', mouth: 'flat', longBeard: '#eeeeea', clothes: 'cardigan', inner: '#d9d2bf', arm: 'low',
      prop: () => P('112,160 148,160 144,184 116,184', '#f4f1e8') + P('130,160 148,160 144,184 130,184', '#d7d2c4') + R(108, 156, 44, 5, '#fff') + R(130, 156, 22, 5, '#e3ded0') + R(116, 168, 28, 4, '#5f8f7b')
        + P('122,150 126,138 130,150', '#fff', ' opacity=".55"') + P('132,146 137,130 141,146', '#fff', ' opacity=".4"') }, crop),
